#!/usr/bin/env node
/**
 * Install prek-managed git hooks for this repository.
 *
 * Run from the repo root:
 *   node scripts/setup-git-hooks.js
 */

import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { execFileSync } from "node:child_process";

const PREK_CONFIG_PATH = resolve(process.cwd(), "prek.toml");
const COMMIT_MSG_VALIDATOR_PATH = resolve(
	process.cwd(),
	"scripts/validate-commit-msg.js",
);
const PREK_HOOK_MARKER = "# File generated by prek: https://github.com/j178/prek";
const PREK_HOOK_CACHE_MARKER = "# configs hook caches stay outside .git";
const PREK_PRE_COMMIT_MARKER = "# configs pre-commit invoked by Git";
const PREK_HOOK_PATCH = [
	PREK_HOOK_CACHE_MARKER,
	"cache_security_guard() {",
	'python3 -I - "$@" <<\'CONFIGS_CACHE_GUARD_PY\'',
	readFileSync(resolve(process.cwd(), "scripts/cache_security.py"), "utf8").trimEnd(),
	"CONFIGS_CACHE_GUARD_PY",
	"}",
	"# configs embedded cache guard v1",
	'if [ "${1:-}" = "--configs-cache-guard" ]; then shift; cache_security_guard "$@"; exit $?; fi',
	'repo_root="$(env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE -u GIT_COMMON_DIR git rev-parse --show-toplevel 2>/dev/null || pwd -P)"',
	'repo_key="$(printf "%s" "$repo_root" | cksum | awk \'{print $1}\')"',
	'if [ -z "${CODEX_HOOK_CACHE_ROOT:-}" ]; then',
	'if [ -n "${HOME:-}" ]; then',
	'  home_root="$(CDPATH= cd -P -- "$HOME" && pwd -P)" || exit 78',
	'  CODEX_HOOK_CACHE_ROOT="$home_root/.cache/codex-runtimes/configs-hook-cache-$(id -u)/$repo_key"',
	'else',
	'  CODEX_HOOK_CACHE_ROOT="${TMPDIR:-/tmp}/configs-hook-cache-$(id -u)/$repo_key"',
	'fi',
	'fi',
	'git_dir="$(env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE -u GIT_COMMON_DIR git -C "$repo_root" rev-parse --git-dir 2>/dev/null || true)"',
	'git_common_dir="$(env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE -u GIT_COMMON_DIR git -C "$repo_root" rev-parse --git-common-dir 2>/dev/null || true)"',
	'if [ -z "$git_dir" ] || [ -z "$git_common_dir" ]; then printf "[prek] unable to resolve Git metadata directories\\n" >&2; exit 78; fi',
	'case "$git_dir" in /*) ;; *) git_dir="$repo_root/$git_dir" ;; esac',
	'case "$git_common_dir" in /*) ;; *) git_common_dir="$repo_root/$git_common_dir" ;; esac',
	'case "$CODEX_HOOK_CACHE_ROOT" in /*) ;; *) CODEX_HOOK_CACHE_ROOT="$repo_root/$CODEX_HOOK_CACHE_ROOT" ;; esac',
	'raw_hook_cache_root="$CODEX_HOOK_CACHE_ROOT"',
	'canonicalize_path() { python3 -I - "$1" <<\'PY\'',
	'from pathlib import Path',
	'import sys',
	'print(Path(sys.argv[1]).expanduser().resolve(strict=False))',
	'PY',
	'}',
	'git_dir="$(canonicalize_path "$git_dir")"',
	'git_common_dir="$(canonicalize_path "$git_common_dir")"',
	'CODEX_HOOK_CACHE_ROOT="$(canonicalize_path "$CODEX_HOOK_CACHE_ROOT")"',
	'case "$CODEX_HOOK_CACHE_ROOT/" in "$git_dir/"*|"$git_common_dir/"*) printf "[prek] hook cache root must stay outside Git metadata: %s\\n" "$CODEX_HOOK_CACHE_ROOT" >&2; exit 78;; esac',
	'cache_security_guard directory "$raw_hook_cache_root" || exit 78',
	'cache_security_guard directory "$raw_hook_cache_root/prek" || exit 78',
	'PREK_HOME="$CODEX_HOOK_CACHE_ROOT/prek"',
	'if ! mkdir -p "$PREK_HOME" || [ ! -d "$PREK_HOME" ] || [ ! -w "$PREK_HOME" ]; then printf "[prek] unable to create writable PREK_HOME: %s\\n" "$PREK_HOME" >&2; exit 78; fi',
	'export CODEX_HOOK_CACHE_ROOT PREK_HOME',
	"",
].join("\n");
const PREK_PRE_COMMIT_PATCH = [
	PREK_PRE_COMMIT_MARKER,
	"export CODEX_PRE_COMMIT_FROM_GIT=1",
	"",
].join("\n");

function patchInstalledPrekHooks() {
	let hooksDir = resolve(process.cwd(), ".git/hooks");
	try {
		const gitHooksPath = execFileSync(
			"git",
			["rev-parse", "--git-path", "hooks"],
			{ encoding: "utf8" },
		).trim();
		if (gitHooksPath.length > 0) {
			hooksDir = resolve(process.cwd(), gitHooksPath);
		}
	} catch {
		// Fallback keeps compatibility when git is unavailable.
	}
	if (!existsSync(hooksDir)) {
		return 0;
	}

	let patchedCount = 0;
	for (const hookName of readdirSync(hooksDir)) {
		const hookPath = resolve(hooksDir, hookName);
		let hookContent = "";
		try {
			hookContent = readFileSync(hookPath, "utf8");
		} catch {
			continue;
		}

		if (!hookContent.includes(PREK_HOOK_MARKER)) {
			continue;
		}
		let patched = hookContent;
		if (hookContent.includes(PREK_HOOK_CACHE_MARKER)) {
			const execMarker = 'exec "$PREK" hook-impl';
			const markerIndex = hookContent.indexOf(PREK_HOOK_CACHE_MARKER);
			const execIndex = hookContent.indexOf(execMarker, markerIndex);
			if (execIndex < 0) {
				continue;
			}
			patched =
				hookContent.slice(0, markerIndex) +
				PREK_HOOK_PATCH +
				hookContent.slice(execIndex);
		} else {
			const legacyPatch = [
				"# Keep prek cache/logs in repo-local .git to avoid home-dir sandbox write failures",
				'PREK_HOME="${PREK_HOME:-$HERE/../.cache/prek}"',
				'mkdir -p "$PREK_HOME" 2>/dev/null || true',
				"export PREK_HOME",
				"",
			].join("\n");
			patched = hookContent.includes(legacyPatch)
				? hookContent.replace(legacyPatch, PREK_HOOK_PATCH)
				: hookContent.replace(
					'fi\n\nexec "$PREK" hook-impl',
					`fi\n\n${PREK_HOOK_PATCH}exec "$PREK" hook-impl`,
				);
		}
		if (hookName === "pre-commit" && !patched.includes(PREK_PRE_COMMIT_MARKER)) {
			patched = patched.replace(
				PREK_HOOK_CACHE_MARKER,
				`${PREK_HOOK_CACHE_MARKER}\n${PREK_PRE_COMMIT_PATCH}`,
			);
		}
		if (patched === hookContent) {
			continue;
		}

		writeFileSync(hookPath, patched);
		patchedCount += 1;
	}

	return patchedCount;
}

function main() {
	if (!existsSync(PREK_CONFIG_PATH)) {
		console.error("Error: prek.toml not found in current directory");
		console.error("  Run this script from your project root.");
		process.exit(1);
	}

	if (!existsSync(COMMIT_MSG_VALIDATOR_PATH)) {
		console.error(
			"Error: scripts/validate-commit-msg.js is required for commit message validation.",
		);
		process.exit(1);
	}

	try {
		console.info("Installing prek git hooks...");
		// Keep canonical hook shims and remove legacy migration wrappers.
		execFileSync("prek", ["install", "--overwrite"], { stdio: "inherit" });
		const patchedCount = patchInstalledPrekHooks();
		if (patchedCount > 0) {
			console.info(`Patched ${patchedCount} prek hook shim(s) with guarded cache handoff`);
		}
		console.info("\n✓ Git hooks installed and active!");
		console.info("\nInstalled git-hook entrypoints:");
		console.info("  • pre-commit: bash scripts/git-hooks/pre-commit.sh");
		console.info("  • pre-push: bash scripts/git-hooks/pre-push.sh");
		console.info("\nAvailable governance wrapper targets:");
		console.info("  • make hooks-pre-commit");
		console.info('  • make hooks-commit-msg HOOK_COMMIT_MSG="feat: example"');
		console.info("  • make hooks-pre-push");
	} catch (error) {
		console.error("\n⚠️  Failed to run `prek install --overwrite`.");
		if (error instanceof Error && "message" in error && error.message) {
			console.error("   " + error.message);
		}
		console.error(
			"   Ensure 'prek' is installed and available on PATH, then rerun the script.",
		);
		process.exit(1);
	}
}

main();
